<?php
if(!defined('BRYXA_API'))exit;
$db->exec('CREATE TABLE IF NOT EXISTS checkout_drafts(id TEXT PRIMARY KEY,data TEXT,session_id TEXT,expires INTEGER); CREATE TABLE IF NOT EXISTS order_access(order_id TEXT PRIMARY KEY,token_hash TEXT);');
function mpConfig():array{return loadDoc('integrations');}
function mpEnabled():bool{$i=mpConfig();return !empty($i['mp_enabled'])&&!empty($i['mp_public_key'])&&!empty($i['mp_access_token'])&&!empty($i['mp_webhook_secret']);}
function mpRequest(string $path,?array $data=null,string $key=''):array{$i=mpConfig();if(empty($i['mp_access_token']))fail('Mercado Pago ainda não configurado.',503);$ch=curl_init('https://api.mercadopago.com'.$path);$headers=['Authorization: Bearer '.$i['mp_access_token'],'Content-Type: application/json'];if($key)$headers[]='X-Idempotency-Key: '.$key;curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>20,CURLOPT_HTTPHEADER=>$headers,CURLOPT_SSL_VERIFYPEER=>true]);if($data!==null)curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($data)]);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if(!$raw||$code<200||$code>=300)fail('Não foi possível confirmar a operação no Mercado Pago. Tente novamente.',502);$result=json_decode($raw,true);if(!is_array($result))fail('Resposta de pagamento inválida.',502);return $result;}
function paymentUpdate(array $payment):array{global $db;$id=(string)($payment['external_reference']??'');$db->beginTransaction();$q=$db->prepare('SELECT data FROM orders WHERE id=?');$q->execute([$id]);$o=json_decode($q->fetchColumn()?:'null',true);if(!$o){$db->rollBack();fail('Pedido de pagamento não encontrado.',404);}if(abs((float)($payment['transaction_amount']??0)-$o['total'])>0.001||($payment['currency_id']??'')!=='BRL'){$db->rollBack();fail('Pagamento não corresponde ao pedido.',409);}if(isset($o['payment_id'])&&(string)$o['payment_id']!==(string)$payment['id']){$db->rollBack();fail('Pagamento não corresponde ao pedido.',409);}if((bool)($payment['live_mode']??false)===(bool)($o['sandbox']??true)){$db->rollBack();fail('Ambiente de pagamento não corresponde ao pedido.',409);}$status=$payment['status'];$previous=$o['payment_status'];$o['payment_id']=(string)$payment['id'];$o['payment_status']=$status;if($status==='approved'&&$previous!=='approved'){$o['timeline'][]=['status'=>'Pagamento aprovado','time'=>date('c'),'source'=>'Mercado Pago'];$o['status']='Recebido';orderEmail($o,'payment_approved',$id.':payment-approved');}if(in_array($status,['rejected','cancelled'])&&!empty($o['reserved_stock'])){$products=loadDoc('products');foreach($o['items'] as $item)foreach($products as &$p)if($p['id']===$item['id'])$p['stock'][$item['size']]=($p['stock'][$item['size']]??0)+$item['quantity'];unset($p);saveDoc('products',$products);$o['reserved_stock']=false;}if($previous!==$status&&in_array($status,['pending','rejected','refunded']))orderEmail($o,['pending'=>'payment_pending','rejected'=>'payment_rejected','refunded'=>'refunded'][$status],$id.':payment:'.$status);saveOrder($o);$db->commit();return $o;}
if($action==='mp-settings'&&$method==='POST'){auth();$b=body();$i=loadDoc('integrations');$i['mp_public_key']=textValue($b['mp_public_key']??'',300);foreach(['mp_access_token','mp_webhook_secret'] as $field){if(!empty($b['clear_'.$field]))$i[$field]='';elseif(!empty($b[$field]))$i[$field]=textValue($b[$field],6000);}$i['mp_sandbox']=!empty($b['mp_sandbox']);$i['mp_enabled']=!empty($b['mp_enabled']);if($i['mp_enabled']&&(empty($i['mp_public_key'])||empty($i['mp_access_token'])||empty($i['mp_webhook_secret'])))fail('Informe Public Key, Access Token e segredo do webhook antes de ativar.');if($i['mp_enabled']&&(!$i['mp_sandbox']||PHP_SAPI!=='cli-server')&&empty($_SERVER['HTTPS']))fail('O pagamento precisa de HTTPS.');saveDoc('integrations',$i);reply(['ok'=>true]);}
if($action==='mp-config'&&$method==='GET'){reply(['enabled'=>mpEnabled(),'public_key'=>mpEnabled()?(mpConfig()['mp_public_key']??''):'','sandbox'=>mpConfig()['mp_sandbox']??true,'demo'=>demoMode()]);}
if($action==='checkout-prepare'&&$method==='POST'){requestLimit('checkout',10);if(!mpEnabled()||demoMode())fail('Pagamento real indisponível nesta prévia.',503);$b=body();$c=$b['customer']??[];$clean=[];foreach(['name','email','postal_code','street','number','complement','neighborhood','city','state'] as $f)$clean[$f]=textValue($c[$f]??'',254);foreach(['name','street','number','neighborhood','city'] as $f)if(!$clean[$f])fail('Confira os dados de entrega.');if(!filter_var($clean['email'],FILTER_VALIDATE_EMAIL)||!preg_match('/^[A-Z]{2}$/',$clean['state']))fail('Confira e-mail e estado.');$clean['postal_code']=preg_replace('/\D/','',$clean['postal_code']);$items=$b['items']??[];$quote=$_SESSION['shipping_quote']??null;if(!$quote||$quote['expires']<time()||$quote['cep']!==$clean['postal_code'])fail('Calcule o frete novamente.');$signature=array_map(fn($x)=>['id'=>$x['id']??'','quantity'=>$x['quantity']??0],$items);if(json_encode($signature)!==$quote['items'])fail('A sacola mudou. Recalcule o frete.');$shipping=null;foreach($quote['quotes'] as $q)if((string)$q['id']===(string)($b['shipping_id']??''))$shipping=$q;if(!$shipping)fail('Escolha o frete.');$catalog=array_column(loadDoc('products'),null,'id');$lines=[];$cents=0;$counts=[];foreach($items as $item){$p=$catalog[$item['id']??'']??null;$size=textValue($item['size']??'',20);$qty=$item['quantity']??0;if(!$p||!$p['active']||!is_int($qty)||$qty<1||$qty>100)fail('Peça inválida.');$key=$p['id'].':'.$size;$counts[$key]=($counts[$key]??0)+$qty;if(($p['stock'][$size]??0)<$counts[$key])fail('Estoque indisponível.');$lines[]=['id'=>$p['id'],'name'=>$p['name'],'price'=>$p['price'],'size'=>$size,'quantity'=>$qty,'custom'=>$item['custom']??null];$cents+=(int)round($p['price']*100)*$qty;}if(!$lines)fail('Sacola vazia.');$pricing=cartPricing($items,textValue($b['coupon']??'',40));if(($quote['pricing']??'')!==hash('sha256',json_encode($pricing)))fail('Os valores ou a promoção mudaram. Recalcule o frete.');foreach($lines as $index=>&$line){$line['nicks']=cleanItemNicks($items[$index]);$line['nick']=cleanItemNick($items[$index]);if(!empty($line['custom']))$line['price']=round($line['price']+(loadDoc('settings')['personalization_price']??0),2);}unset($line);$id='BRYXA-'.strtoupper(bin2hex(random_bytes(6)));$draft=['id'=>$id,'customer'=>$clean,'items'=>$lines,'shipping'=>$shipping,'subtotal'=>$pricing['subtotal'],'discount'=>$pricing['discount'],'gift'=>$pricing['gift'],'total'=>round($pricing['net']+$shipping['price'],2),'payment_status'=>'not_created','status'=>'Aguardando pagamento','sandbox'=>mpConfig()['mp_sandbox']??true,'timeline'=>[['status'=>'Pedido recebido','time'=>date('c'),'source'=>'checkout']],'created'=>date('c')];$db->prepare('INSERT INTO checkout_drafts VALUES(?,?,?,?)')->execute([$id,json_encode($draft),session_id(),time()+1800]);reply(['draft_id'=>$id,'amount'=>$draft['total'],'public_key'=>mpConfig()['mp_public_key'],'sandbox'=>$draft['sandbox']]);}
if($action==='mp-pay'&&$method==='POST'){requestLimit('mp-pay',15);if(!mpEnabled()||demoMode())fail('Pagamento indisponível.',503);$b=body();$q=$db->prepare('SELECT * FROM checkout_drafts WHERE id=? AND session_id=? AND expires>?');$q->execute([$b['draft_id']??'',session_id(),time()]);$row=$q->fetch(PDO::FETCH_ASSOC);if(!$row)fail('Sessão de pagamento expirada.',403);$draft=json_decode($row['data'],true);$f=$b['formData']??[];$method=textValue($f['payment_method_id']??'',40);if($method!=='pix'&&empty($f['token']))fail('Forma de pagamento inválida.');$identification=$f['payer']['identification']??null;$payload=['transaction_amount'=>$draft['total'],'description'=>'Pedido '.$draft['id'].' · BRYXA','external_reference'=>$draft['id'],'payment_method_id'=>$method,'payer'=>['email'=>$draft['customer']['email']]];if($identification)$payload['payer']['identification']=$identification;if($method!=='pix'){$payload['token']=textValue($f['token'],300);$payload['installments']=max(1,min(12,(int)($f['installments']??1)));if(isset($f['issuer_id']))$payload['issuer_id']=textValue((string)$f['issuer_id'],40);}$domain=preg_replace('/[^a-zA-Z0-9.-]/','',loadDoc('settings')['domain']);$payload['notification_url']='https://'.$domain.'/api/index.php?action=mp-webhook';$q=$db->prepare('SELECT data FROM orders WHERE id=?');$q->execute([$draft['id']]);$existing=$q->fetchColumn();if(!$existing){$token=bin2hex(random_bytes(32));$draft['access_link']='https://'.$domain.'/acompanhar/#'.$token;$db->prepare('INSERT INTO order_access VALUES(?,?)')->execute([$draft['id'],hash('sha256',$token)]);$db->beginTransaction();$products=loadDoc('products');foreach($draft['items'] as $item){$found=false;foreach($products as &$p)if($p['id']===$item['id']){if(($p['stock'][$item['size']]??0)<$item['quantity']){$db->rollBack();fail('Estoque alterado. Refaça a compra.',409);}$p['stock'][$item['size']]-=$item['quantity'];$found=true;}unset($p);if(!$found){$db->rollBack();fail('Produto indisponível.');}}saveDoc('products',$products);$draft['reserved_stock']=true;$db->prepare('INSERT INTO orders VALUES(?,?,?)')->execute([$draft['id'],json_encode($draft),date('c')]);$db->commit();orderEmail($draft,'order_created',$draft['id'].':created');}$payment=mpRequest('/v1/payments',$payload,$draft['id']);$o=paymentUpdate($payment);$token=substr($o['access_link'],strrpos($o['access_link'],'#')+1);$qr=$payment['point_of_interaction']['transaction_data']??[];reply(['order'=>$o,'token'=>$token,'qr_code'=>$qr['qr_code']??'','qr_code_base64'=>$qr['qr_code_base64']??'']);}
if($action==='mp-webhook'&&$method==='POST'){$i=mpConfig();if(empty($i['mp_webhook_secret']))fail('Webhook não configurado.',503);$id=(string)($_GET['data_id']??'');if(!preg_match('/^[0-9]+$/',$id))fail('Identificador inválido.',400);$signature=$_SERVER['HTTP_X_SIGNATURE']??'';$parts=[];foreach(explode(',',$signature) as $part){$kv=explode('=',$part,2);if(count($kv)===2)$parts[trim($kv[0])]=trim($kv[1]);}$ts=$parts['ts']??'';$request=$_SERVER['HTTP_X_REQUEST_ID']??'';if(!ctype_digit($ts)||!$request||empty($parts['v1']))fail('Assinatura inválida.',401);$manifest='id:'.$id.';request-id:'.$request.';ts:'.$ts.';';if(!hash_equals(hash_hmac('sha256',$manifest,$i['mp_webhook_secret']),$parts['v1']))fail('Assinatura inválida.',401);$payment=mpRequest('/v1/payments/'.$id);paymentUpdate($payment);reply(['ok'=>true]);}
